package com.rulecraft.decisionops.deployment;

import com.rulecraft.decisionops.expressions.language.ExpressionLanguage;import com.rulecraft.decisionops.platform.web.DomainProblemException;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;import tools.jackson.core.JacksonException;import tools.jackson.databind.*;

@Component
public class CapturedDecisionRuntime {
    private final ObjectMapper mapper;private final ExpressionLanguage language;
    public CapturedDecisionRuntime(ObjectMapper mapper,ExpressionLanguage language){this.mapper=mapper;this.language=language;}
    public JsonNode parse(String artifact){try{return mapper.readTree(artifact);}catch(JacksonException failure){throw problem("RC-DEPLOY-ARTIFACT-JSON","The promoted artifact is not valid JSON.");}}
    public void validateArtifact(JsonNode root){var content=requiredObject(root,"content");requiredObject(content,"service");var inputs=requiredObject(content,"inputs");var outputs=requiredObject(content,"outputs");var nodes=requiredObject(content,"nodes");var edges=requiredObject(content,"edges");var implementations=requiredObject(content,"implementations");requiredObject(content,"types");if(nodes.isEmpty()||outputs.isEmpty())bad("RC-DEPLOY-ARTIFACT-INCOMPLETE","The promoted artifact does not contain an executable graph.");inputs.properties().forEach(entry->validateField(entry.getKey(),entry.getValue()));outputs.properties().forEach(entry->validateField(entry.getKey(),entry.getValue()));nodes.properties().forEach(entry->{var node=entry.getValue();if(!node.isObject()||node.path("kind").asString().isBlank()||!node.path("ports").isObject())bad("RC-DEPLOY-ARTIFACT-NODE","The promoted artifact contains an invalid graph node.");if("DECISION".equals(node.path("kind").asString())){var implementation=implementations.get(entry.getKey());if(implementation==null||!Set.of("TABLE","EXPRESSION").contains(implementation.path("kind").asString()))bad("RC-DEPLOY-ARTIFACT-IMPLEMENTATION","Every deployed decision must have a captured implementation.");if("EXPRESSION".equals(implementation.path("kind").asString())&&!language.validateCapturedSyntax(implementation.path("source").asString()).isEmpty())bad("RC-DEPLOY-ARTIFACT-EXPRESSION","A captured expression cannot be parsed safely.");}});edges.propertyNames().forEach(edge->{if(!edge.contains(" -> "))bad("RC-DEPLOY-ARTIFACT-EDGE","The promoted artifact contains an invalid graph connection.");});}
    public Evaluation evaluate(String artifact,Map<String,JsonNode> supplied){var root=parse(artifact);validateArtifact(root);var content=root.get("content");var inputs=content.get("inputs");var types=content.get("types");var values=supplied==null?Map.<String,JsonNode>of():supplied;validateBudget(values);var expected=new HashSet<String>();inputs.propertyNames().forEach(expected::add);values.keySet().stream().filter(key->!expected.contains(key)).findFirst().ifPresent(key->{throw problem("RC-DEPLOY-INPUT-UNKNOWN","Unknown deployed input '"+key+"'.");});inputs.properties().forEach(entry->{var value=values.get(entry.getKey());if(value==null){if(entry.getValue().path("required").asBoolean())bad("RC-DEPLOY-INPUT-MISSING","Provide required input '"+entry.getKey()+"'.");}else if(!validType(value,entry.getValue().path("type").asString(),types,0))bad("RC-DEPLOY-INPUT-TYPE","Input '"+entry.getKey()+"' does not match the deployed contract.");});
        var nodes=content.get("nodes");var edges=content.get("edges");var implementations=content.get("implementations");var endpointValues=new HashMap<String,JsonNode>();nodes.properties().forEach(entry->{var node=entry.getValue();if("INPUT".equals(node.path("kind").asString())){var value=values.get(node.path("serviceFieldKey").asString());node.get("ports").properties().forEach(port->{if(port.getKey().startsWith("OUTPUT:")&&value!=null)endpointValues.put(entry.getKey()+"."+port.getKey().substring(7),value);});}});var incoming=new HashMap<String,String>();edges.propertyNames().forEach(edge->{var parts=edge.split(" -> ",2);incoming.put(parts[1],parts[0]);});var pending=new TreeSet<String>();nodes.properties().forEach(entry->{if("DECISION".equals(entry.getValue().path("kind").asString()))pending.add(entry.getKey());});var decisions=new ArrayList<DecisionTrace>();while(!pending.isEmpty()){String ready=null;for(var key:pending){var ports=nodes.get(key).get("ports");var blocked=ports.properties().stream().filter(port->port.getKey().startsWith("INPUT:")).map(port->incoming.get(key+"."+port.getKey().substring(6))).filter(Objects::nonNull).anyMatch(source->!endpointValues.containsKey(source));if(!blocked){ready=key;break;}}if(ready==null)bad("RC-DEPLOY-ORDER","The deployed graph could not be ordered deterministically.");var context=new LinkedHashMap<String,JsonNode>();for(var port:nodes.get(ready).get("ports").properties().stream().filter(item->item.getKey().startsWith("INPUT:")).sorted(Comparator.comparingInt(item->item.getValue().path("position").asInt())).toList()){var key=port.getKey().substring(6);var source=incoming.get(ready+"."+key);if(source!=null&&endpointValues.containsKey(source))context.put(key,endpointValues.get(source));}var result=evaluateDecision(ready,nodes.get(ready),implementations.get(ready),context);var output=nodes.get(ready).get("ports").properties().stream().filter(item->item.getKey().startsWith("OUTPUT:")).findFirst().orElseThrow();if(!validType(result.value(),output.getValue().path("type").asString(),types,0))bad("RC-DEPLOY-OUTPUT-TYPE","Decision '"+ready+"' produced a value outside its captured output type.");endpointValues.put(ready+"."+output.getKey().substring(7),result.value());decisions.add(result);pending.remove(ready);}
        var resultOutputs=new LinkedHashMap<String,JsonNode>();content.get("outputs").properties().forEach(field->{var node=nodes.properties().stream().filter(entry->"OUTPUT".equals(entry.getValue().path("kind").asString())&&field.getKey().equals(entry.getValue().path("serviceFieldKey").asString())).findFirst().orElseThrow(()->problem("RC-DEPLOY-OUTPUT-NODE","The deployed contract output is not connected to a graph output."));var port=node.getValue().get("ports").properties().stream().filter(item->item.getKey().startsWith("INPUT:")).findFirst().orElseThrow();var source=incoming.get(node.getKey()+"."+port.getKey().substring(6));var value=source==null?null:endpointValues.get(source);if(value==null){if(field.getValue().path("required").asBoolean())bad("RC-DEPLOY-OUTPUT-MISSING","The required output '"+field.getKey()+"' was not produced.");}else if(!validType(value,field.getValue().path("type").asString(),types,0))bad("RC-DEPLOY-OUTPUT-TYPE","Output '"+field.getKey()+"' does not match the deployed contract.");else resultOutputs.put(field.getKey(),value);});return new Evaluation(resultOutputs,decisions);}
    private DecisionTrace evaluateDecision(String key,JsonNode node,JsonNode implementation,Map<String,JsonNode> context){var kind=implementation.path("kind").asString();if("EXPRESSION".equals(kind)){var evaluated=language.evaluateCaptured(implementation.path("source").asString(),context);if(!evaluated.successful()){var issue=evaluated.issues().getFirst();bad(issue.code(),issue.message());}return new DecisionTrace(key,node.path("name").asString(),kind,null,evaluated.value());}var matches=new ArrayList<JsonNode>();for(var rule:implementation.path("rules")){if(!rule.path("enabled").asBoolean())continue;var match=true;for(var input:rule.path("inputs").properties()){var operator=input.getValue().path("operator").asString();if(!"ANY".equals(operator)){var expected=parseValue(input.getValue().path("value").asString());if(!equal(context.get(input.getKey()),expected)){match=false;break;}}}if(match)matches.add(rule);}if(matches.isEmpty())bad("RC-DEPLOY-NO-MATCH","Decision table '"+key+"' did not match any rule.");if("UNIQUE".equals(implementation.path("hitPolicy").asString())&&matches.size()!=1)bad("RC-DEPLOY-UNIQUE-VIOLATION","A UNIQUE deployed table matched more than one rule.");var match=matches.getFirst();return new DecisionTrace(key,node.path("name").asString(),kind,match.path("id").asString(null),parseValue(match.path("output").asString()));}
    private boolean validType(JsonNode value,String type,JsonNode types,int depth){if(value==null||value.isNull()||depth>24)return false;return switch(type){case "TEXT"->value.isString();case "NUMBER"->value.isNumber();case "BOOLEAN"->value.isBoolean();case "DATE"->date(value);case "DATE_TIME"->dateTime(value);default->{if(!type.startsWith("CUSTOM:")){yield false;}var definition=types.get(type.substring(7));if(definition==null){yield false;}yield switch(definition.path("kind").asString()){case "ENUM"->value.isString()&&definition.path("values").has(value.asString());case "LIST"->value.isArray()&&value.size()<=2000&&value.values().stream().allMatch(item->validType(item,definition.path("itemType").asString(),types,depth+1));case "OBJECT"->{if(!value.isObject()){yield false;}var fields=definition.path("fields");var unknown=value.propertyNames().stream().anyMatch(key->!fields.has(key));if(unknown){yield false;}yield fields.properties().stream().allMatch(field->{var item=value.get(field.getKey());return item==null?!field.getValue().path("required").asBoolean():validType(item,field.getValue().path("type").asString(),types,depth+1);});}default->false;};}};}
    private boolean date(JsonNode value){try{LocalDate.parse(value.asString());return value.isString();}catch(DateTimeException failure){return false;}}private boolean dateTime(JsonNode value){try{OffsetDateTime.parse(value.asString());return value.isString();}catch(DateTimeException failure){return false;}}
    private void validateField(String key,JsonNode field){if(key.isBlank()||!field.isObject()||field.path("type").asString().isBlank())bad("RC-DEPLOY-ARTIFACT-CONTRACT","The promoted artifact contains an invalid contract field.");}private JsonNode requiredObject(JsonNode parent,String key){var value=parent==null?null:parent.get(key);if(value==null||!value.isObject())throw problem("RC-DEPLOY-ARTIFACT-SHAPE","The promoted artifact is missing '"+key+"'.");return value;}private JsonNode parseValue(String raw){try{return mapper.readTree(raw);}catch(JacksonException failure){throw problem("RC-DEPLOY-ARTIFACT-VALUE","A captured rule value is not valid JSON.");}}private boolean equal(JsonNode left,JsonNode right){if(left==null||right==null)return left==right;return left.isNumber()&&right.isNumber()?left.decimalValue().compareTo(right.decimalValue())==0:left.equals(right);}private void validateBudget(Map<String,JsonNode> supplied){var queue=new ArrayDeque<JsonNode>();supplied.values().stream().filter(Objects::nonNull).forEach(queue::add);var count=0;while(!queue.isEmpty()){var value=queue.removeFirst();if(++count>10000||(value.isArray()&&value.size()>2000)||(value.isString()&&value.asString().length()>12000))bad("RC-DEPLOY-INPUT-LIMIT","Evaluation inputs exceed the runtime sandbox limits.");value.values().forEach(queue::addLast);}}
    private void bad(String code,String detail){throw problem(code,detail);}private DomainProblemException problem(String code,String detail){return new DomainProblemException(HttpStatus.BAD_REQUEST,code,detail);}public record DecisionTrace(String nodeKey,String nodeName,String implementation,String matchedRuleId,JsonNode value){}public record Evaluation(Map<String,JsonNode> outputs,List<DecisionTrace> decisions){}
}
